package com.shengxu.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.metadata.IPage; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.baomidou.mybatisplus.core.toolkit.IdWorker;
import com.shengxu.dto.MusicDtos.*; import com.shengxu.entity.*; import com.shengxu.mapper.*; import com.shengxu.utils.BusinessException;
import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service
public class MusicTaskService {
 private final MusicTaskMapper tasks; private final MusicLibraryMapper library; private final UserCreditMapper credits; private final CreditRecordMapper records; private final SunoApiService suno;
 public MusicTaskService(MusicTaskMapper t,MusicLibraryMapper l,UserCreditMapper c,CreditRecordMapper r,SunoApiService s){tasks=t;library=l;credits=c;records=r;suno=s;}
 @Transactional public MusicTask create(Long userId,String key,CreateTask in){
  if(!suno.configured())throw new BusinessException(HttpStatus.SERVICE_UNAVAILABLE,"音乐生成服务尚未配置");
  if(key==null||key.isBlank()||key.length()>64)throw new BusinessException(HttpStatus.BAD_REQUEST,"缺少有效的 Idempotency-Key");
  MusicTask existing=tasks.selectOne(new LambdaQueryWrapper<MusicTask>().eq(MusicTask::getUserId,userId).eq(MusicTask::getIdempotencyKey,key));if(existing!=null)return existing;
  validate(in);int cost=Boolean.TRUE.equals(in.maxMode())?20:10;if(credits.deduct(userId,cost)!=1)throw new BusinessException(HttpStatus.PAYMENT_REQUIRED,"积分不足，本次生成需要 "+cost+" 积分");
  MusicTask t=new MusicTask();t.setId(IdWorker.getId());t.setUserId(userId);t.setIdempotencyKey(key);t.setPrompt(in.prompt().trim());t.setStyle(in.style());t.setMood(in.mood());t.setVocalType(in.vocalType());t.setLanguage(in.language());t.setLyricsMode(in.lyricsMode());t.setInputLyrics(in.lyrics());t.setSongTitle(in.songTitle());t.setNegativeTags(in.negativeTags());t.setModelVersion(in.model()==null||in.model().isBlank()?"suno-v6":in.model());t.setMaxMode(Boolean.TRUE.equals(in.maxMode())?1:0);t.setWeirdness(in.weirdness()==null?50:in.weirdness());t.setStyleWeight(in.styleWeight()==null?70:in.styleWeight());t.setDuration(in.duration());t.setVariety(in.variety());t.setSourceClipId(in.sourceClipId());t.setSourceType(in.sourceType()==null||in.sourceType().isBlank()?"GENERATED":in.sourceType().toUpperCase());t.setSourceAudioUrl(in.sourceAudioUrl());t.setSourceTitle(in.sourceTitle());t.setAudioWeight(in.audioWeight());t.setVoiceId(in.voiceId());t.setSoundType(in.soundType());t.setSoundBpm(in.soundBpm());t.setSoundKey(in.soundKey());t.setSoundLoop(Boolean.TRUE.equals(in.soundLoop())?1:0);t.setStatus("WAITING");t.setSubmitStage("CREATED");t.setCost(cost);t.setPollCount(0);tasks.insert(t);
  UserCredit balance=credits.selectOne(new LambdaQueryWrapper<UserCredit>().eq(UserCredit::getUserId,userId));CreditRecord r=new CreditRecord();r.setId(IdWorker.getId());r.setUserId(userId);r.setTaskId(t.getId());r.setRecordType("CONSUME");r.setAmount(-cost);r.setBalanceAfter(balance.getBalance());r.setBusinessNo("TASK:"+t.getId()+":CONSUME");r.setRemark(Boolean.TRUE.equals(in.maxMode())?"Max Mode 生成音乐":"生成音乐");records.insert(r);return t;
 }
 private void validate(CreateTask in){Set<String> styles=Set.of("Pop","Rock","HipHop","EDM","Lo-fi","古风"),moods=Set.of("快乐","悲伤","治愈","热血"),vocals=Set.of("AUTO","MALE","FEMALE","INSTRUMENTAL"),modes=Set.of("AI","USER"),sources=Set.of("GENERATED","CUSTOM","UPLOAD","REMIX","SOUND");boolean advanced="CUSTOM".equalsIgnoreCase(in.sourceType());if(in.style()==null||in.style().isBlank()||(!advanced&&!styles.contains(in.style()))||(!advanced&&(in.mood()==null||!moods.contains(in.mood())))||!vocals.contains(in.vocalType())||!modes.contains(in.lyricsMode())||(in.sourceType()!=null&&!in.sourceType().isBlank()&&!sources.contains(in.sourceType().toUpperCase())))throw new BusinessException(HttpStatus.BAD_REQUEST,"生成参数不受支持");if(in.sourceClipId()!=null&&in.sourceClipId().toLowerCase().startsWith("pending:"))throw new BusinessException(HttpStatus.BAD_REQUEST,"来源歌曲尚未完成，不能用于续写");if("USER".equals(in.lyricsMode())&&!"INSTRUMENTAL".equals(in.vocalType())&&(in.lyrics()==null||in.lyrics().isBlank()))throw new BusinessException(HttpStatus.BAD_REQUEST,"请输入歌词");if("SOUND".equalsIgnoreCase(in.sourceType())&&(in.prompt()==null||in.prompt().isBlank()))throw new BusinessException(HttpStatus.BAD_REQUEST,"请输入音效描述");if(in.duration()!=null&&(in.duration()<1||in.duration()>480))throw new BusinessException(HttpStatus.BAD_REQUEST,"时长必须在 1 到 480 秒之间");if(in.variety()!=null&&(in.variety()<0||in.variety()>4))throw new BusinessException(HttpStatus.BAD_REQUEST,"Variety 必须在 0 到 4 之间");}
 public TaskView get(Long uid,Long id){MusicTask t=owned(uid,id);List<MusicLibrary> tracks=library.selectList(new LambdaQueryWrapper<MusicLibrary>().eq(MusicLibrary::getTaskId,id).orderByAsc(MusicLibrary::getCreatedAt));return view(t,tracks);}
 public PageView<TaskView> list(Long uid,long page,long size){IPage<MusicTask> p=tasks.selectPage(new Page<>(page,Math.min(size,50)),new LambdaQueryWrapper<MusicTask>().eq(MusicTask::getUserId,uid).orderByDesc(MusicTask::getCreatedAt));return new PageView<>(p.getRecords().stream().map(t->view(t,List.of())).toList(),p.getTotal(),p.getCurrent(),p.getSize());}
 MusicTask owned(Long uid,Long id){MusicTask t=tasks.selectById(id);if(t==null||!t.getUserId().equals(uid))throw new BusinessException(HttpStatus.NOT_FOUND,"任务不存在");return t;}
 private TaskView view(MusicTask t,List<MusicLibrary> ls){return new TaskView(t.getId(),t.getPrompt(),t.getStyle(),t.getMood(),t.getVocalType(),t.getLanguage(),t.getLyricsMode(),t.getSongTitle(),t.getStatus(),t.getSubmitStage(),t.getErrorMessage(),t.getNegativeTags(),t.getModelVersion(),Integer.valueOf(1).equals(t.getMaxMode()),t.getWeirdness(),t.getStyleWeight(),t.getDuration(),t.getVariety(),t.getSourceClipId(),t.getSourceType(),t.getSourceAudioUrl(),t.getSourceTitle(),t.getAudioWeight(),t.getVoiceId(),t.getSoundType(),t.getSoundBpm(),t.getSoundKey(),Integer.valueOf(1).equals(t.getSoundLoop()),t.getCreatedAt(),ls.stream().map(MusicLibraryService::view).toList());}
}
